let emptyImg: HTMLImageElement | undefined;

export function getEmptyImg() {
  return emptyImg ?? (emptyImg = createEmptyImg());
}

function createEmptyImg() {
  const _emptyImage = document.createElement("img");
  // Set the src to be a 0x0 gif
  _emptyImage.src = "data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==";

  return _emptyImage;
}

function downloadImage(url: string, filename: string) {
  const encodedFilename = encodeURIComponent(filename);
  fetch(url, {
    headers: {
      "Cache-Control": "no-cache",
      Pragma: "no-cache",
    },
  })
    .then(async (response) => {
      const disposition = response.headers.get("Content-Disposition");
      const match = disposition && disposition.match(/filename="(.+)"/);
      const name = match ? match[1] : encodedFilename;
      const blob = await response.blob();
      return { blob, name };
    })
    .then(({ blob, name }) => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    });
}

const lazy = (dom: any) => {
  const imgDom: any = dom.children[0];
  if(!imgDom.src || imgDom.src !== imgDom.dataset.src) {
    imgDom.src = imgDom.dataset.src;
  }
  imgDom.onload = () => {
    dom.style.backgroundColor = '';
    dom.style.aspectRatio = '';
  }
};

const ImgUtils = {
  get emptyImg() { return getEmptyImg(); },
  createEmptyImg: createEmptyImg,
  downloadImage: downloadImage,
  lazy: lazy,
};

export default ImgUtils;
